#include <atomic>
#include <iostream>
#include <thread>

int main()
{
    int result{};
    std::atomic<bool> ready{false};
    std::jthread writer{[&] {
        result = 42;
        ready.store(true, std::memory_order_release);
        ready.notify_one();
    }};
    ready.wait(false, std::memory_order_acquire);
    std::cout << result << '\n';
}
